package com.ccb.testmanagement.report;

import com.ccb.common.api.PageQuery;import com.ccb.common.api.PageResult;import com.ccb.common.exception.BusinessException;import com.ccb.common.exception.ErrorCode;import com.ccb.security.model.AuthUser;import com.fasterxml.jackson.core.type.TypeReference;import com.fasterxml.jackson.databind.ObjectMapper;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.LocalDateTime;import java.util.*;import java.util.concurrent.ThreadLocalRandom;

/** 报告服务保留范围、版本和审计规则；所有持久化由 Repository/Mapper XML 承担。 */
@Service public class TestReportService {
 private static final Set<String> DOMAINS=Set.of("application-assembly","user-testing","non-functional","security"); public static final List<String> CHAPTERS=List.of("OVERVIEW","SCOPE_STAT","EXECUTION_STAT","DEFECT_STAT","SCOPE_DETAIL","DEFECT_DETAIL"); private final TestReportRepository repository;private final ObjectMapper mapper;
 public TestReportService(TestReportRepository repository,ObjectMapper mapper){this.repository=repository;this.mapper=mapper;}
 public Map<String,Object> tree(String d,long p,AuthUser u){scope(d,p,u);Map<String,Object>x=base(d,p,u);return Map.of("project",repository.project(x),"systems",repository.systems(x),"specials",repository.specials(x));}
 public Map<String,Object> options(String d,long p,Long sys,AuthUser u){scope(d,p,u);if(sys!=null)system(d,p,sys,u);Map<String,Object>x=base(d,p,u);return Map.of("rounds",repository.rounds(x),"cycles",repository.cycles(x),"sections",CHAPTERS);}
 public PageResult<Map<String,Object>> list(String d,long p,Long sys,Long special,String rawScope,String keyword,PageQuery page,AuthUser u){scope(d,p,u);String scope=normalizeScope(rawScope,sys,special);validateScope(d,p,scope,sys,special,u);Map<String,Object>x=base(d,p,u);x.put("scope",scope);x.put("systemId","SYSTEM".equals(scope)?sys:null);x.put("specialNodeId","SPECIAL".equals(scope)?special:null);x.put("keyword",keyword==null?null:keyword.trim());long total=repository.reportCount(x);x.put("offset",(page.page()-1)*page.size());x.put("size",page.size());return new PageResult<>(repository.reportPage(x),total,page.page(),page.size());}
 @Transactional public Map<String,Object> generate(String d,long p,Long sys,Long special,String rawScope,Long reportId,Map<String,Object>b,AuthUser u){scope(d,p,u);String scope=normalizeScope(rawScope,sys,special);validateScope(d,p,scope,sys,special,u);String name=required(b.get("report_name"),"报告名称",100),type=required(b.get("report_type"),"报告类型",16).toUpperCase(Locale.ROOT);if(!Set.of("PROJECT","ROUND","CYCLE").contains(type))throw bad("报告类型无效");Long round=longOrNull(b.get("round_id")),cycle=longOrNull(b.get("cycle_id"));if("PROJECT".equals(type)){round=null;cycle=null;}if("ROUND".equals(type)&&round==null)throw bad("请选择关联轮次");if("CYCLE".equals(type)&&(round==null||cycle==null))throw bad("请选择关联轮次和周期");validateRound(d,p,round,cycle,u);String source=String.valueOf(b.getOrDefault("source_type","LIVE")).toUpperCase(Locale.ROOT);if(!Set.of("LIVE","SNAPSHOT").contains(source))throw bad("数据来源无效");if("SNAPSHOT".equals(source)&&round==null)throw bad("项目报告仅支持当前实时数据");List<String> sections=sections(b.get("sections"));long saved=reportId==null?next():reportId;Map<String,Object>x=base(d,p,u);x.put("id",saved);x.put("scope",scope);x.put("systemId","SYSTEM".equals(scope)?sys:null);x.put("specialNodeId","SPECIAL".equals(scope)?special:null);x.put("name",name);x.put("type",type);x.put("roundId",round);x.put("cycleId",cycle);x.put("source",source);x.put("sectionsJson",json(sections));if(reportId==null){if(repository.sameNameCount(x)>0)throw conflict("当前节点已有同名报告");repository.insertReport(x);}else{Map<String,Object> existing=requireReport(reportId,d,p,u.tenantId());if(!sameScope(existing,scope,sys,special))throw bad("报告不属于当前树节点");repository.updateReport(x);}int versionNo=nextVersion(saved,u.tenantId());long versionId=next();Map<String,Object> facts=snapshotForSource(d,p,"SYSTEM".equals(scope)?sys:null,round,cycle,sections,source,u);repository.insertVersion(params("id",versionId,"tenantId",u.tenantId(),"reportId",saved,"versionNo",versionNo,"snapshotJson",json(facts),"userId",u.id()));repository.updateCurrentVersion(params("tenantId",u.tenantId(),"reportId",saved,"versionNo",versionNo,"userId",u.id()));audit(d,p,saved,versionId,reportId==null?"GENERATE":"REGENERATE",u);return detail(d,p,saved,versionId,u);}
 public Map<String,Object> detail(String d,long p,long report,Long selected,AuthUser u){Map<String,Object> row=requireReport(report,d,p,u.tenantId());List<Map<String,Object>> versions=repository.reportVersions(params("tenantId",u.tenantId(),"reportId",report));if(versions.isEmpty())return Map.of("report",row,"versions",List.of());long versionId=selected==null?number(versions.get(0).get("id")):selected;Map<String,Object> version=requireVersion(versionId,report,u.tenantId());return Map.of("report",row,"versions",versions,"version",version,"snapshot",jsonMap(version.get("snapshot_json")),"supplements",repository.supplements(params("tenantId",u.tenantId(),"versionId",versionId)));}
 public List<Map<String,Object>> history(String d,long p,long report,AuthUser u){requireReport(report,d,p,u.tenantId());return repository.history(params("tenantId",u.tenantId(),"reportId",report));}
 @Transactional public void supplement(String d,long p,long report,long version,Map<String,Object>b,AuthUser u){requireReport(report,d,p,u.tenantId());requireVersion(version,report,u.tenantId());String chapter=required(b.get("chapter_code"),"章节",32).toUpperCase(Locale.ROOT);if(!CHAPTERS.contains(chapter))throw bad("章节无效");Map<String,Object>x=params("tenantId",u.tenantId(),"versionId",version,"chapter",chapter,"html",String.valueOf(b.getOrDefault("content_html","")).trim(),"userId",u.id());if(repository.supplementCount(x)>0)repository.updateSupplement(x);else{x.put("id",next());repository.insertSupplement(x);}audit(d,p,report,version,"SUPPLEMENT",u);}
 @Transactional public void delete(String d,long p,long id,AuthUser u){Map<String,Object> row=requireReport(id,d,p,u.tenantId());repository.insertConfigurationAudit(params("id",next(),"tenantId",u.tenantId(),"domain",d,"projectId",p,"reportId",id,"userId",u.id(),"detailJson",json(Map.of("report_name",String.valueOf(row.get("report_name")),"version_count",nextVersion(id,u.tenantId())-1))));audit(d,p,id,null,"DELETE",u);repository.deleteReport(params("reportId",id,"tenantId",u.tenantId()));}
 @Transactional public void recordDownload(String d,long p,long id,Long version,String format,AuthUser u){requireReport(id,d,p,u.tenantId());if(version!=null)requireVersion(version,id,u.tenantId());audit(d,p,id,version,"DOWNLOAD_"+format.toUpperCase(Locale.ROOT),u);}
 public Map<String,Object> snapshot(String d,long p,Long sys,Long round,Long cycle,List<String> sections,AuthUser u){Map<String,Object>x=base(d,p,u);x.put("systemId",sys);x.put("roundId",round);x.put("cycleId",cycle);long executions=repository.executionCount(x),success=repository.executionSuccessCount(x),failed=repository.executionFailedCount(x),blocked=repository.executionBlockedCount(x);Map<String,Object> facts=new LinkedHashMap<>();facts.put("snapshot_at",LocalDateTime.now().toString());facts.put("sections",sections);facts.put("scope_total",repository.scopeCount(x));facts.put("case_total",repository.caseCount(x));facts.put("execution_total",executions);facts.put("execution_success",success);facts.put("execution_failed",failed);facts.put("execution_blocked",blocked);facts.put("execution_rate",rate(success+failed+blocked,executions));facts.put("success_rate",rate(success,executions));facts.put("defect_total",repository.defectCount(x));facts.put("defect_open",repository.openDefectCount(x));facts.put("scope_details",repository.scopeDetails(x));facts.put("defect_details",repository.defectDetails(x));return facts;}
 private Map<String,Object> snapshotForSource(String d,long p,Long sys,Long round,Long cycle,List<String> sections,String source,AuthUser u){if("LIVE".equals(source))return snapshot(d,p,sys,round,cycle,sections,u);if(sys!=null)throw bad("系统级报告暂不支持项目轮次统计快照，请选择当前实时数据");List<Map<String,Object>> rows=repository.archivedSnapshot(params("tenantId",u.tenantId(),"domain",d,"projectId",p,"roundId",round));if(rows.isEmpty())throw bad("所选轮次尚未归档统计快照，请先在分析统计归档");Map<String,Object> archived=jsonMap(rows.get(0).get("snapshot_json"));Map<String,Object> facts=archived.get("summary") instanceof Map<?,?> raw?copy(raw):new LinkedHashMap<>(archived);facts.put("snapshot_at",String.valueOf(rows.get(0).get("archived_at")));facts.put("sections",sections);facts.put("source_type","SNAPSHOT");return facts;}
 private void validateScope(String d,long p,String scope,Long sys,Long special,AuthUser u){if("SYSTEM".equals(scope))system(d,p,sys,u);if("SPECIAL".equals(scope)&&!repository.specialExists(params("tenantId",u.tenantId(),"domain",d,"projectId",p,"specialNodeId",special)))throw bad("专项节点不属于当前项目");}private void validateRound(String d,long p,Long round,Long cycle,AuthUser u){if(round!=null&&!repository.roundExists(params("tenantId",u.tenantId(),"domain",d,"projectId",p,"roundId",round)))throw bad("轮次不属于当前项目");if(cycle!=null&&!repository.cycleExists(params("tenantId",u.tenantId(),"roundId",round,"cycleId",cycle)))throw bad("周期不属于所选轮次");}private Map<String,Object> requireReport(long id,String d,long p,long tenant){Map<String,Object>x=repository.report(params("reportId",id,"tenantId",tenant,"domain",d,"projectId",p));if(x==null||x.isEmpty())throw bad("报告不存在或不属于当前项目");return x;}private Map<String,Object> requireVersion(long id,long report,long tenant){Map<String,Object>x=repository.version(params("versionId",id,"reportId",report,"tenantId",tenant));if(x==null||x.isEmpty())throw bad("报告版本不存在");return x;}private int nextVersion(long report,long tenant){return repository.nextVersion(params("reportId",report,"tenantId",tenant));}private void system(String d,long p,long sys,AuthUser u){if(!repository.participatingSystem(params("tenantId",u.tenantId(),"domain",d,"projectId",p,"systemId",sys)))throw bad("请选择已参测系统");}private void scope(String d,long p,AuthUser u){if(!DOMAINS.contains(d))throw bad("测试大类无效");if(!repository.projectExists(params("projectId",p,"tenantId",u.tenantId())))throw bad("项目不存在或无权访问");}
 private String normalizeScope(String raw,Long sys,Long special){String scope=raw==null||raw.isBlank()?(sys!=null?"SYSTEM":special!=null?"SPECIAL":"PROJECT"):raw.toUpperCase(Locale.ROOT);if(!Set.of("PROJECT","SYSTEM","SPECIAL").contains(scope))throw bad("报告范围无效");if("PROJECT".equals(scope)&&(sys!=null||special!=null))throw bad("项目级报告不能绑定系统或专项");if("SYSTEM".equals(scope)&&(sys==null||special!=null))throw bad("请选择报告所属系统");if("SPECIAL".equals(scope)&&(special==null||sys!=null))throw bad("请选择报告所属专项");return scope;}private boolean sameScope(Map<String,Object> r,String scope,Long sys,Long special){if(!scope.equals(String.valueOf(r.get("scope_type"))))return false;if("SYSTEM".equals(scope))return Objects.equals(number(r.get("physical_subsystem_id")),sys);if("SPECIAL".equals(scope))return Objects.equals(number(r.get("special_node_id")),special);return true;}private List<String> sections(Object raw){if(!(raw instanceof Collection<?> list))return CHAPTERS;List<String> out=list.stream().map(String::valueOf).map(x->x.toUpperCase(Locale.ROOT)).filter(CHAPTERS::contains).distinct().toList();return out.isEmpty()?CHAPTERS:out;}private Map<String,Object> base(String d,long p,AuthUser u){return params("tenantId",u.tenantId(),"domain",d,"projectId",p);}private void audit(String d,long p,long report,Long version,String action,AuthUser u){repository.insertTrace(params("id",next(),"tenantId",u.tenantId(),"domain",d,"projectId",p,"reportId",report,"versionId",version,"action",action,"userId",u.id()));}
 private String json(Object o){try{return mapper.writeValueAsString(o);}catch(Exception e){throw bad("快照序列化失败");}}private Map<String,Object> jsonMap(Object o){try{return mapper.readValue(String.valueOf(o),new TypeReference<>(){});}catch(Exception e){return Map.of();}}private static Map<String,Object> copy(Map<?,?> raw){Map<String,Object> out=new LinkedHashMap<>();raw.forEach((k,v)->out.put(String.valueOf(k),v));return out;}private static Map<String,Object> params(Object... v){Map<String,Object>x=new HashMap<>();for(int i=0;i<v.length;i+=2)x.put(String.valueOf(v[i]),v[i+1]);return x;}private static double rate(long p,long total){return total==0?0:Math.round(p*10000D/total)/100D;}private static long next(){return System.currentTimeMillis()*1000+ThreadLocalRandom.current().nextInt(1000);}private static long number(Object v){return ((Number)v).longValue();}private static Long longOrNull(Object v){try{if(v==null||String.valueOf(v).isBlank()||"null".equals(String.valueOf(v)))return null;return Long.parseLong(String.valueOf(v));}catch(Exception e){throw bad("编号无效");}}private static String required(Object v,String n,int max){String s=v==null?"":String.valueOf(v).trim();if(s.isBlank()||s.length()>max)throw bad(n+"无效");return s;}private static BusinessException bad(String s){return new BusinessException(ErrorCode.BAD_REQUEST,s);}private static BusinessException conflict(String s){return new BusinessException(ErrorCode.CONFLICT,s);}
}
